api.look('agent');
const cx = api.w/2, cy = 340, R = 130;
const k = api.seg(t, 0, 1.6);
api.circle(cx, cy, R, {c:'fg', w:5, k});
for (let i = 0; i < 20; i++) {
  const a = -Math.PI/2 + i/20*Math.PI*2;
  const kk = api.stag(t, i, {gap:0.03, dur:0.3, from:0.3});
  const r1 = R+10, r2 = R+(i%5===0?30:20);
  api.line(cx+Math.cos(a)*r1, cy+Math.sin(a)*r1, cx+Math.cos(a)*r2, cy+Math.sin(a)*r2, {c:i%5===0?'accent':'dim', w:3, k:kk});
}
api.arc(cx, cy, R-16, -Math.PI/2, -Math.PI/2+Math.PI*2*api.seg(t,0.5,3.4), {c:'accent', w:10});
api.counter(20, cx, cy+14, {k, suf:'', size:84});
api.text('minutes', cx, cy+64, {size:22, c:'dim', align:'center', k:api.seg(t,1,1.8)});
api.text('No equipment', cx, 600, {size:34, weight:700, align:'center', k:api.seg(t,1.4,2.6)});
api.say('Twenty minutes. No equipment.', 0.3, 3.3);

api.look('agent');
const cx = api.w/2;
api.text('4 moves', cx, 90, {size:36, weight:700, align:'center', k:api.seg(t,0,0.8)});
const names = ['Squat','Push-up','Plank','Lunge'];
const cols = ['accent','a2','a3','good'];
for (let i = 0; i < 4; i++) {
  const col = i%2, row = (i/2)|0;
  const x = cx + (col?1:-1)*92, y = 290 + row*240;
  const k = api.stag(t, i, {gap:0.9, dur:0.9, from:0.4});
  const bob = Math.sin(t*3+i*1.5)*8*k;
  const c0 = cols[i];
  api.circle(x, y, 84, {c:c0, w:3, a:0.15*k, fill:c0, k});
  const hx = x, hy = y-44+bob;
  api.circle(hx, hy, 14, {c:'fg', w:4, k});
  if (i===0) { // squat
    api.line(hx, hy+14, hx, y+4+bob, {c:'fg', w:5, k});
    api.line(hx, y+4+bob, hx+30, y+10+bob, {c:'fg', w:5, k});
    api.line(hx+30, y+10+bob, hx+30, y+50, {c:'fg', w:5, k});
    api.line(hx, y-20+bob, hx+34, y-20+bob, {c:'fg', w:5, k});
  } else if (i===1) { // push-up
    api.line(x-60, y+30+bob, x+60, y+6, {c:'fg', w:5, k});
    api.circle(x+70, y-4, 12, {c:'fg', w:4, k});
    api.line(x+40, y+10, x+40, y+44, {c:'fg', w:5, k});
  } else if (i===2) { // plank
    api.line(x-62, y+34, x+52, y+34, {c:'fg', w:5, k});
    api.circle(x+66, y+26, 12, {c:'fg', w:4, k});
    api.line(x+36, y+34, x+36, y+56, {c:'fg', w:5, k});
  } else { // lunge
    api.line(hx, hy+14, hx, y+10, {c:'fg', w:5, k});
    api.line(hx, y+10, hx+44, y+30, {c:'fg', w:5, k});
    api.line(hx+44, y+30, hx+44, y+58, {c:'fg', w:5, k});
    api.line(hx, y+10, hx-40, y+58, {c:'fg', w:5, k});
  }
  api.text(names[i], x, y+112, {size:22, weight:700, align:'center', k});
}
api.say('Four simple moves.', 0.4, 5.5);

api.look('agent');
const cx = api.w/2;
api.text('40 on, 20 off', cx, 90, {size:36, weight:700, align:'center', k:api.seg(t,0,0.8)});
const cyc = 6, p = (t % cyc) / cyc;
const on = p < 2/3;
const bx = 30, bw = api.w-60, by = 330;
api.rect(bx, by, bw, 60, {c:'fg', w:3, r:12});
api.rect(bx+3, by+3, (bw-6)*2/3, 54, {c:'accent', fill:'accent', a:0.3, r:10});
api.text('WORK', bx+(bw*2/3)/2, by+42, {size:22, weight:700, align:'center', c:'accent'});
api.text('REST', bx+bw*5/6, by+42, {size:22, weight:700, align:'center', c:'a2'});
const px = bx + bw*p;
api.line(px, by-24, px, by+84, {c:'fg', w:4});
api.dot(px, by-28, 9, {c:'fg'});
api.glow(cx, 560, 90, {c:on?'accent':'a2'});
const s = on ? 1+0.12*Math.sin(t*9) : 1;
api.shape(on?'bolt':'cloud', cx, 560, 110*s, {c:on?'accent':'a2', w:5});
api.text(on?'Go hard':'Breathe', cx, 680, {size:30, weight:700, align:'center', c:on?'accent':'a2'});
api.say('Forty seconds on, twenty off.', 0.4, 5.5);

api.look('agent');
const cx = api.w/2;
api.text('5 rounds', cx, 90, {size:36, weight:700, align:'center', k:api.seg(t,0,0.8)});
const names = ['Squat','Push-up','Plank','Lunge'];
const cols = ['accent','a2','a3','good'];
for (let r = 0; r < 5; r++) {
  const y = 190 + r*100;
  const kr = api.stag(t, r, {gap:0.5, dur:0.5, from:0.3});
  api.text('R'+(r+1), 40, y+8, {size:20, c:'dim', k:kr});
  for (let i = 0; i < 4; i++) {
    const x = 110 + i*72;
    const k = api.stag(t, r*4+i, {gap:0.1, dur:0.25, from:0.5});
    api.rect(x, y-24, 62, 48, {c:cols[i], fill:cols[i], a:0.7, r:10, k});
  }
}
const total = api.seg(t,2.8,5);
api.bracePlaceholder;
api.text('4 min a round', cx, 700, {size:26, weight:700, align:'center', k:api.seg(t,3,4)});
api.say('Five rounds, four minutes each.', 0.4, 5.5);

api.look('agent');
const cx = api.w/2, cy = 330;
api.glow(cx, cy, 160, {c:'good'});
api.circle(cx, cy, 120, {c:'good', w:6, k:api.seg(t,0,1.2)});
api.shape('check', cx, cy, 130, {c:'good', w:8, k:api.seg(t,0.8,1.8)});
api.swarm(60, t, {mode:'burst', cx, cy, rx:200, ry:200, c:'accent', k:api.seg(t,1.2,4)});
api.kinetic('20 minutes', cx, 580, {mode:'pop', size:42, k:api.seg(t,1.4,3), t});
api.text('Done. No gear.', cx, 640, {size:24, c:'dim', align:'center', k:api.seg(t,2.4,3.4)});
api.say('Done. No gear needed.', 0.4, 4.5);
